<?php
require __DIR__.'/security.php';security_establish_session($ou);
$cash=funds_create('Correction cash','cash','AFN',1000);
function expenseFixture($amount,$cash=0){global $pdo;$pdo->prepare("INSERT INTO expenses (shop_id,expense_type,category,amount,expense_date,description,currency_code) VALUES (?,'مصارف','Other',?,?,?,'AFN')")->execute([shop_id(),$amount,date('Y-m-d'),'Mistaken synthetic expense']);$id=(int)$pdo->lastInsertId();$_POST=['cash_account_id'=>$cash];finance_currency_event('expenses',$id,'create');$_POST=[];return $id;}
$expense=expenseFixture(20,$cash);$key=bin2hex(random_bytes(16));$correction=finance_correct('expense',$expense,date('Y-m-d'),'Incorrect expense entry',$key);check(funds_balance($cash)==='1000.00','paid expense correction restores recorded cash once');check(finance_correct('expense',$expense,date('Y-m-d'),'Incorrect expense entry',$key)===$correction,'financial correction retry is idempotent');
$q=$pdo->prepare('SELECT amount FROM expenses WHERE id=?');$q->execute([$expense]);check(dec_round($q->fetchColumn())==='20.00','correction preserves original expense amount');$q=$pdo->prepare('SELECT id FROM '.live_documents_source('expenses').' WHERE id=?');$q->execute([$expense]);check(!$q->fetchColumn(),'cancelled mistaken expense excluded from operational reports');
$caught=false;try{finance_correct('expense',$expense,date('Y-m-d'),'Another cancellation',bin2hex(random_bytes(16)));}catch(InvalidArgumentException $e){$caught=true;}check($caught,'source document cannot be cancelled twice');
$unpaid=expenseFixture(20);finance_pay_expense($unpaid,$cash,10,date('Y-m-d'),bin2hex(random_bytes(16)));finance_correct('expense',$unpaid,date('Y-m-d'),'Wrong unpaid expense',bin2hex(random_bytes(16)));check(funds_balance($cash)==='1000.00','part-paid expense correction reverses cash and remaining payable together');$caught=false;try{finance_pay_expense($unpaid,$cash,10,date('Y-m-d'),bin2hex(random_bytes(16)));}catch(InvalidArgumentException $e){$caught=true;}check($caught,'cancelled expense cannot be settled again');
$pdo->prepare("INSERT INTO capital (shop_id,amount,transaction_type,source_description,transaction_date,currency_code) VALUES (?,100,'سرمایه','Wrong capital',?,'AFN')")->execute([shop_id(),date('Y-m-d')]);$capital=(int)$pdo->lastInsertId();$_POST=['action'=>'add_capital','cash_account_id'=>$cash];finance_currency_event('capital',$capital,'create');$_POST=[];finance_correct('capital',$capital,date('Y-m-d'),'Mistaken capital receipt',bin2hex(random_bytes(16)));check(funds_balance($cash)==='1000.00','capital correction reverses recorded receipt with cash balance check');
$q=$pdo->prepare('SELECT id FROM '.live_documents_source('capital').' WHERE id=?');$q->execute([$capital]);check(!$q->fetchColumn(),'cancelled capital excluded without requiring a view');
$afn=array_values(array_filter(currency_account_summary(),fn($r)=>$r['code']==='AFN'))[0];check(dec_units($afn['expenses'])===0&&dec_units($afn['capital_in'])===0,'currency reports omit corrected expense and capital while preserving source rows');
$pdo->prepare("INSERT INTO debts (shop_id,customer_name,total_amount,paid_amount,remaining_amount,debt_type,currency_code) VALUES (?,'Wrong debt',50,0,50,'receivable','AFN')")->execute([shop_id()]);$debt=(int)$pdo->lastInsertId();finance_settle_debt($debt,$cash,10,date('Y-m-d'),bin2hex(random_bytes(16)));finance_correct('debt',$debt,date('Y-m-d'),'Incorrect standalone debt',bin2hex(random_bytes(16)));check(funds_balance($cash)==='1000.00','standalone debt correction reverses actual partial receipts');$q=$pdo->prepare('SELECT remaining_amount FROM debts WHERE id=?');$q->execute([$debt]);check(dec_units($q->fetchColumn())===0,'cancelled standalone debt has no outstanding obligation');
$purchase=inventory_save_purchase(['purchase_mode'=>'single','purchase_request_key'=>bin2hex(random_bytes(16)),'name'=>'Correction loss stock','unit'=>'unit','quantity'=>10,'purchase_price'=>10,'sale_price'=>15,'expenses'=>0,'currency_code'=>'AFN','purchase_date'=>date('Y-m-d')],$owner);$q=$pdo->prepare('SELECT stock_id FROM inventory_purchase_items WHERE purchase_id=? AND shop_id=?');$q->execute([$purchase['id'],shop_id()]);$stock=(int)$q->fetchColumn();$pdo->prepare("INSERT INTO expenses (shop_id,expense_type,category,amount,expense_date,description,currency_code,stock_id,loss_qty,inventory_cost,inventory_currency_code) VALUES (?,'ضرر','Damage',20,?,'Wrong loss','AFN',?,2,20,'AFN')")->execute([shop_id(),date('Y-m-d'),$stock]);$loss=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE stock SET quantity=8,inventory_value=80,capital_amount=80,damaged_qty=2 WHERE id=? AND shop_id=?')->execute([$stock,shop_id()]);finance_currency_event('expenses',$loss,'create');$caught=false;try{finance_correct('loss',$loss,date('Y-m-d'),'Wrong physical damage',bin2hex(random_bytes(16)));}catch(InvalidArgumentException $e){$caught=true;}check($caught&&!finance_is_corrected('loss',$loss),'stock loss reversal requires explicit physical recovery confirmation');finance_correct('loss',$loss,date('Y-m-d'),'Goods confirmed saleable again',bin2hex(random_bytes(16)),true);$q=$pdo->prepare('SELECT quantity,inventory_value FROM stock WHERE id=?');$q->execute([$stock]);$row=$q->fetch();check(dec_round($row['quantity'],3)==='10.000'&&dec_round($row['inventory_value'])==='100.00','verified loss correction restores exact stock quantity and acquisition value');
$expense2=expenseFixture(5,$cash);finance_close_period(date('Y-m-d'));$caught=false;try{finance_correct('expense',$expense2,date('Y-m-d'),'Closed source expense',bin2hex(random_bytes(16)));}catch(InvalidArgumentException $e){$caught=true;}check($caught&&!finance_is_corrected('expense',$expense2),'closed-period cancellation is rejected without changing source state');
$q=$pdo->prepare('SELECT SUM(debit-credit) FROM journal_details WHERE shop_id=?');$q->execute([shop_id()]);check(dec_units($q->fetchColumn())===0,'all correction journals remain exactly balanced');
echo "Financial correction scenarios completed.\n";
